Here is the commit message:
xen-netfront: Remove BUGs on paged skb data which crosses a
 page boundary

These BUGs can be erroneously triggered by frags which refer to
tail pages within a compound page. The data in these pages may
overrun the hardware page while still being contained within the
compound page, but since compound_order() evaluates to 0 for tail
pages the assertion fails. The code already iterates through
subsequent pages correctly in this scenario, so the BUGs are
unnecessary and can be removed.

Fixes: f36c374782e4 ("xen/netfront: handle compound page fragments on transmit")
Cc: <stable@vger.kernel.org> # 3.7+
Signed-off-by: Seth Forshee <seth.forshee@canonical.com>
Reviewed-by: David Vrabel <david.vrabel@citrix.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the incorrect triggering of assertions (BUG_ON) when handling fragments that refer to tail pages within a compound page. The assertions checked for conditions that could be valid in certain scenarios, leading to false positives. Specifically, the checks did not account for the fact that data could overrun the hardware page while still being contained within the compound page, as the `compound_order()` function evaluates to 0 for tail pages.

Here is the patch:

 static void xennet_make_frags(struct sk_buff *skb, struct netfront_queue *queue,
 			      struct xen_netif_tx_request *tx)
 {
 	char *data = skb->data;
 	unsigned long mfn;
 	RING_IDX prod = queue->tx.req_prod_pvt;
 	int frags = skb_shinfo(skb)->nr_frags;
 	unsigned int offset = offset_in_page(data);
 	unsigned int len = skb_headlen(skb);
 	unsigned int id;
 	grant_ref_t ref;
 	int i;

 	/* While the header overlaps a page boundary (including being
 	   larger than a page), split it it into page-sized chunks. */
 	while (len > PAGE_SIZE - offset) {
 		tx->size = PAGE_SIZE - offset;
 		tx->flags |= XEN_NETTXF_more_data;
 		len -= tx->size;
 		data += tx->size;
 		offset = 0;

 		id = get_id_from_freelist(&queue->tx_skb_freelist, queue->tx_skbs);
 		queue->tx_skbs[id].skb = skb_get(skb);
 		tx = RING_GET_REQUEST(&queue->tx, prod++);
 		tx->id = id;
 		ref = gnttab_claim_grant_reference(&queue->gref_tx_head);
 		BUG_ON((signed short)ref < 0);

 		mfn = virt_to_mfn(data);
 		gnttab_grant_foreign_access_ref(ref, queue->info->xbdev->otherend_id,
 						mfn, GNTMAP_readonly);

 		queue->grant_tx_page[id] = virt_to_page(data);
 		tx->gref = queue->grant_tx_ref[id] = ref;
 		tx->offset = offset;
 		tx->size = len;
 		tx->flags = 0;
 	}

 	/* Grant backend access to each skb fragment page. */
 	for (i = 0; i < frags; i++) {
 		skb_frag_t *frag = skb_shinfo(skb)->frags + i;
 		struct page *page = skb_frag_page(frag);

 		len = skb_frag_size(frag);
 		offset = frag->page_offset;

-		/* Data must not cross a page boundary. */
-		BUG_ON(len + offset > PAGE_SIZE<<compound_order(page));
-
 		/* Skip unused frames from start of page */
 		page += offset >> PAGE_SHIFT;
 		offset &= ~PAGE_MASK;

 		while (len > 0) {
 			unsigned long bytes;

-			BUG_ON(offset >= PAGE_SIZE);
-
 			bytes = PAGE_SIZE - offset;
 			if (bytes > len)
 				bytes = len;

 			tx->flags |= XEN_NETTXF_more_data;

 			id = get_id_from_freelist(&queue->tx_skb_freelist,
 						  queue->tx_skbs);
 			queue->tx_skbs[id].skb = skb_get(skb);
 			tx = RING_GET_REQUEST(&queue->tx, prod++);
 			tx->id = id;
 			ref = gnttab_claim_grant_reference(&queue->gref_tx_head);
 			BUG_ON((signed short)ref < 0);

 			mfn = pfn_to_mfn(page_to_pfn(page));
 			gnttab_grant_foreign_access_ref(ref,
 							queue->info->xbdev->otherend_id,
 							mfn, GNTMAP_readonly);

 			queue->grant_tx_page[id] = page;
 			tx->gref = queue->grant_tx_ref[id] = ref;
 			tx->offset = offset;
 			tx->size = bytes;
 			tx->flags = 0;

 			offset += bytes;
 			len -= bytes;

 			/* Next frame */
 			if (offset == PAGE_SIZE && len) {
 				BUG_ON(!PageCompound(page));
 				page++;
 				offset = 0;
 			}
 		}
 	}

 	queue->tx.req_prod_pvt = prod;
 }



